var (
	Todos_CreateTodoTool   = newTool("todos-create_todo_v1", `Creates a todo. POST /v1/{parent=calendars/*}/todos body: the todo itself Server-assigned fields on the request body are ignored: `+"`"+`name`+"`"+`, `+"`"+`uid`+"`"+`, `+"`"+`etag`+"`"+` and the timestamps are set by the server regardless. Supply `+"`"+`todo_id`+"`"+` to choose the final path segment. Not idempotent. Retrying after a timeout may create a second todo; supply `+"`"+`todo_id`+"`"+` if the caller needs retry safety. ALREADY_EXISTS     that todo_id is taken INVALID_ARGUMENT   a field violates its buf.validate constraint PERMISSION_DENIED  caller may not create here`, Todos_CreateTodoSchemaJSON, Todos_CreateTodoOutputSchemaJSON, nil, "", nil)
	Todos_DeleteTodoTool   = newTool("todos-delete_todo_v1", `Deletes a todo. DELETE /v1/{name=calendars/*/todos/*} Soft delete: the todo is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. Recover it with Undelete before then. Idempotent in effect but not in reporting: a second delete returns NOT_FOUND rather than succeeding silently. NOT_FOUND          no such todo ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Todos_DeleteTodoSchemaJSON, Todos_DeleteTodoOutputSchemaJSON, nil, "", nil)
	Todos_GetTodoTool      = newTool("todos-get_todo_v1", `Retrieves one todo. GET /v1/{name=calendars/*/todos/*} Safe and idempotent. Read the `+"`"+`etag`+"`"+` here and pass it back on update or delete to make the write conditional. NOT_FOUND          no such todo, or it is soft-deleted INVALID_ARGUMENT   name does not match calendars/*/todos/* PERMISSION_DENIED  caller may not read it`, Todos_GetTodoSchemaJSON, Todos_GetTodoOutputSchemaJSON, nil, "", nil)
	Todos_ListTodosTool    = newTool("todos-list_todos_v1", `Lists the todos of a calendar. GET /v1/{parent=calendars/*}/todos Paginated per AIP-158: pass `+"`"+`page_size`+"`"+` (defaults to 50, capped at 1000) and the `+"`"+`next_page_token`+"`"+` from the previous response. Page tokens are opaque and may expire; do not construct or store them. Scoped to one calendar through `+"`"+`parent`+"`"+`; there is no cross-calendar listing. Filtering uses AIP-160 over the resource's own fields. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection`, Todos_ListTodosSchemaJSON, Todos_ListTodosOutputSchemaJSON, nil, "", nil)
	Todos_UndeleteTodoTool = newTool("todos-undelete_todo_v1", `Restores a soft-deleted todo. POST /v1/{name=calendars/*/todos/*}:undelete Valid only before `+"`"+`expire_time`+"`"+`; after that the todo is gone and this returns NOT_FOUND. Clears `+"`"+`delete_time`+"`"+` and `+"`"+`expire_time`+"`"+`. NOT_FOUND          no such todo, or already purged ALREADY_EXISTS     the todo is not deleted PERMISSION_DENIED  caller may not restore it`, Todos_UndeleteTodoSchemaJSON, Todos_UndeleteTodoOutputSchemaJSON, nil, "", nil)
	Todos_UpdateTodoTool   = newTool("todos-update_todo_v1", `Updates a todo. PATCH /v1/{todo.name=calendars/*/todos/*} body: the todo itself A partial update: only fields named in `+"`"+`update_mask`+"`"+` are written. An empty mask writes every mutable field, clearing anything the caller left unset -- pass a mask unless that is the intent. OUTPUT_ONLY and IMMUTABLE fields are rejected rather than silently dropped. Idempotent. Pass the `+"`"+`etag`+"`"+` read from Get to make the write conditional. NOT_FOUND          no such todo ABORTED            etag does not match the stored resource INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it`, Todos_UpdateTodoSchemaJSON, Todos_UpdateTodoOutputSchemaJSON, nil, "", nil)
)

